/**
 * Checks the live Gnani APIs and the LLM, in the order that can change the plan:
 * streaming STT per language, cross-language cloning, then full turn latency.
 * Audio is generated by Timbre, so no real recordings are involved.
 * Clips are written to tmp/ so a person can judge how they sound.
 */
import { mkdirSync, writeFileSync } from "node:fs";
import { MIC_SAMPLE_RATE, PLAYBACK_SAMPLE_RATE } from "../shared/protocol";
import type { LanguageCode } from "../shared/protocol";
import { pcmToWav } from "../server/audio";
import { loadConfig } from "../server/config";
import { GnaniSpeech } from "../server/providers/gnani";
import { LlmTranslator } from "../server/providers/llm";
import type { VoiceChoice } from "../server/providers/types";

const config = loadConfig();
const speech = new GnaniSpeech(config);
const llm = new LlmTranslator(config);
mkdirSync("tmp", { recursive: true });

/** Downsamples 24 kHz PCM to 16 kHz by linear interpolation. */
function to16k(pcm: Buffer): Buffer {
  const ratio = PLAYBACK_SAMPLE_RATE / MIC_SAMPLE_RATE;
  const inSamples = Math.floor(pcm.length / 2);
  const outSamples = Math.floor(inSamples / ratio);
  const out = Buffer.alloc(outSamples * 2);
  for (let i = 0; i < outSamples; i++) {
    const position = i * ratio;
    const index = Math.floor(position);
    const a = pcm.readInt16LE(index * 2);
    const b = index + 1 < inSamples ? pcm.readInt16LE((index + 1) * 2) : a;
    out.writeInt16LE(Math.round(a + (b - a) * (position - index)), i * 2);
  }
  return out;
}

async function tts(text: string, language: LanguageCode, voice: VoiceChoice = { gender: "female" }) {
  const chunks: Buffer[] = [];
  const start = Date.now();
  let firstByteMs = 0;
  const result = await speech.synthesize({ text, language, voice }, (pcm) => {
    firstByteMs ||= Date.now() - start;
    chunks.push(pcm);
  });
  return { pcm: Buffer.concat(chunks), firstByteMs, ...result };
}

async function transcribe(pcm16k: Buffer, language: LanguageCode) {
  const session = speech.openStt({ language, onError: (error) => console.error("  stt:", error.message) });
  const frameBytes = 1024;
  for (let offset = 0; offset < pcm16k.length; offset += frameBytes) {
    session.write(pcm16k.subarray(offset, offset + frameBytes));
    await new Promise((resolve) => setTimeout(resolve, 16));
  }
  const start = Date.now();
  const text = await session.finish();
  return { text, finishMs: Date.now() - start };
}

async function step(name: string, run: () => Promise<void>) {
  process.stdout.write(`\n== ${name}\n`);
  try {
    await run();
  } catch (error) {
    console.log(`  FAILED: ${String(error)}`);
    process.exitCode = 1;
  }
}

const SAMPLES: [LanguageCode, string][] = [
  ["ta-IN", "எனக்கு மூன்று நாட்களாக வயிற்று வலி இருக்கிறது."],
  ["hi-IN", "मुझे तीन दिन से पेट में दर्द है।"],
  ["bn-IN", "আমার তিন দিন ধরে পেটে ব্যথা হচ্ছে।"],
  ["ml-IN", "എനിക്ക് മൂന്ന് ദിവസമായി വയറുവേദനയുണ്ട്."],
];

await step("1. Timbre to Prisma streaming round trip", async () => {
  for (const [language, text] of SAMPLES) {
    const audio = await tts(text, language);
    writeFileSync(`tmp/tts-${language}.wav`, pcmToWav(audio.pcm, PLAYBACK_SAMPLE_RATE));
    const heard = await transcribe(to16k(audio.pcm), language);
    console.log(`  ${language} tts first byte ${audio.firstByteMs} ms, stt after commit ${heard.finishMs} ms`);
    console.log(`    said:  ${text}\n    heard: ${heard.text || "(nothing)"}`);
  }
});

await step("2. Cross-language cloning: Hindi reference speaks Tamil", async () => {
  const reference = await tts(
    "नमस्ते, मेरा नाम आशा है। मैं आज सुबह जल्दी उठी और बाज़ार गई। वहाँ से सब्ज़ियाँ और फल लाई। फिर घर आकर खाना बनाया और बच्चों को स्कूल भेजा।",
    "hi-IN",
  );
  const seconds = reference.pcm.length / 2 / PLAYBACK_SAMPLE_RATE;
  console.log(`  reference clip ${seconds.toFixed(1)} s`);
  const embedding = await speech.createVoice(pcmToWav(reference.pcm, PLAYBACK_SAMPLE_RATE));
  console.log(`  embedding shape ${JSON.stringify(embedding.shape)}, dtype ${embedding.dtype}`);
  for (const [language, text] of SAMPLES.slice(0, 2)) {
    const clone = await tts(text, language, { gender: "female", embedding });
    writeFileSync(`tmp/clone-${language}.wav`, pcmToWav(clone.pcm, PLAYBACK_SAMPLE_RATE));
    console.log(
      `  ${language} first byte ${clone.firstByteMs} ms, fallback used: ${clone.usedFallback}, saved tmp/clone-${language}.wav`,
    );
  }
  console.log("  Listen to tmp/clone-*.wav to judge whether the voice carried over.");
});

await step("3. Translation", async () => {
  const start = Date.now();
  const result = await llm.translate({
    text: "ಊಟದ ನಂತರ ದಿನಕ್ಕೆ ಎರಡು ಬಾರಿ 500 mg ಮಾತ್ರೆ ತೆಗೆದುಕೊಳ್ಳಿ",
    from: "kn-IN",
    to: "bn-IN",
    relationship: "doctor",
    speakerIsCaller: false,
    history: [],
  });
  console.log(`  ${Date.now() - start} ms`);
  console.log(`  ${JSON.stringify(result, null, 2)}`);
});
